/bin/zsh -c "python3 -c 'import math, sympy as s, mpmath as mp; ps=list(s.primerange(2,200001)); names=[\"k"'^2+1","k''^3+2","2k+1"]; products=[1.,1.,1.];
for p in ps:
 r1a=1 if p==2 else (2 if p%4==1 else 0); r2a=0 if p==2 else r1a
 r1b=1 if p in [2,3] or p%3==2 else (3 if pow(p-2,(p-1)//3,p)==1 else 0); r2b=0 if p==2 else (3 if p==3 else r1b)
 r1c=0 if p==2 else 1; r2c=r1c
 for i,(r1,r2) in enumerate([(r1a,r2a),(r1b,r2b),(r1c,r2c)]):
  a0=1+r2/(p*p*(p*p-2)); a1=1+r1/(p*(p*p-2)); a2=1+1/(p*p-2)
  b=a0+(p*r1-r2)/(p*p*(p*p-2))*math.sqrt(p)+(p-r1)/(p*(p*p-2))*p
  products[i]*=(1-2/(p*p))*(1-1/p)*b
print("factor",float(-mp.mpf(8)/3*mp.zeta(-mp.mpf(1)/2)))
for n,h in zip(names,products): print(n,"H",h,"C",float(-mp.mpf(8)/3*mp.zeta(-mp.mpf(1)/2))*h)
print("bad root cubic mod9",[a for a in range(9) if (a**3+2)%9==0])'"'"

