/bin/zsh -c "python3 -c 'import json, math, sympy as sp, mpmath as mp; data=json.load(open(\"results.json\")); ps=list(sp.primerange(2,1000001)); gamma=float(mp.euler); c=6/math.pi**2
for idx,(name,pdat) in enumerate(data[\"polynomials\"].items()):
 R=1.; W0=1.; cp=1.; der=0.; factors={}
 for p in ps:
  if idx==0: r1=1 if p==2 else (2 if p%4==1 else 0); r2=0 if p==2 else r1
  elif idx==1: r1=1 if p in [2,3] or p%3==2 else (3 if pow(p-2,(p-1)//3,p)==1 else 0); r2=0 if p in [2,3] else r1
  else: r1=0 if p==2 else 1; r2=r1
  a0=1+r2/(p*p*(p*p-2)); delta1=(p*r1-r2)/(p*p*(p*p-2)); delta2=(p-r1)/(p*(p*p-2)); a1=a0+delta1; a2=a1+delta2; b=a0+delta1/p+delta2/p**2; cc=1-2/p**2
  R*=cc*b; W0*=cc*a0; cp*=1-1/p**2; der+=-math.log(p)*(delta1/p+2*delta2/p**2)/b
  if p<=250: factors[p]=(a0,a1,a2)
 B=R*(gamma+der-1.5)
 def w(h):
  ans=W0
  for p,e in sp.factorint(h).items():
   a0,a1,a2=factors[p]; ans*= (a1 if e==1 else a2)/a0
  return ans
 print(name,\"R\",R,\"B\",B)
 for row in pdat[\"rows\"][-8:]:
  r=row[\"ratio_actual\"]; H=1/r; theta=sum(w(h)/h*(H-h)**2 for h in range(1,int(H)+1)); F=R*math.log(H)+B+cp/H-theta/H**2; pred=F/r**1.5
  print(round(r,6),\"observed\",round(row[\"normalised\"],9),\"profile\",round(pred,9),\"relative\",round(row[\"normalised\"]/pred-1,7))
'"

